# ! [feature (proc_macro_hygiene , decl_macro)] # [macro_use] extern crate rocket ; # [macro_use] extern crate diesel ; mod schema ; use crate :: schema :: companies ; use diesel :: prelude :: * ; use diesel :: { Insertable , Queryable } ; use rocket_contrib :: databases :: { database , diesel :: PgConnection } ; use rocket_contrib :: json :: Json ; use serde_derive :: { Deserialize , Serialize } ; # [database ("postgres")] struct DbConn (PgConnection) ; # [derive (Queryable , Serialize , Deserialize)] struct Company { id : i32 , name : String , } # [derive (Insertable , Deserialize)] # [table_name = "companies"] struct NewCompany { name : String , } # [get ("/" , format = "application/json")] fn get_companies (conn : DbConn) -> Json < Vec < Company > > { let companies = companies :: table . order (companies :: id . desc ()) . load :: < Company > (& * conn) . unwrap () ; Json (companies) } # [post ("/" , data = "<new_company>" , format = "application/json")] fn create_company (conn : DbConn , new_company : Json < NewCompany >) -> Json < Company > { let result = diesel :: insert_into (companies :: table) . values (& new_company . 0) . get_result (& * conn) . unwrap () ; Json (result) } # [put ("/" , data = "<company>" , format = "application/json")] fn edit_company (conn : DbConn , company : Json < Company >) -> Json < Company > { let target = companies :: table . find (company . id) ; let result = diesel :: update (target) . set (companies :: columns :: name . eq (& company . name)) . get_result (& * conn) . unwrap () ; Json (result) } # [get ("/")] fn index () -> & 'static str { "Hello, world!" } # [get ("/<name>")] fn hello (name : String) -> String { format ! ("Hello, {}!" , name) } fn main () { rocket :: ignite () . attach (DbConn :: fairing ()) . mount ("/hello" , routes ! [index , hello]) . mount ("/companies" , routes ! [get_companies , create_company , edit_company] ,) . launch () ; }